const mats=new Map();export function mat(color){if(!mats.has(color))mats.set(color,new T.MeshToonMaterial({color}));return mats.get(color);}
export function label(text,color='#fff5d6'){const c=document.createElement('canvas');c.width=384;c.height=72;const x=c.getContext('2d');x.font='26px sans-serif';x.textAlign='center';x.fillStyle='#314c39dd';x.beginPath();x.roundRect(2,2,380,64,18);x.fill();x.fillStyle=color;x.fillText(text,192,45);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),transparent:true}));s.scale.set(3,.55,1);return s;}
function canvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
function pixelOval(c,x,y,rx,ry,color){c.fillStyle=color;for(let row=-Math.ceil(ry);row<=ry;row+=2){const span=Math.round(rx*Math.sqrt(Math.max(0,1-row*row/(ry*ry))));c.fillRect(Math.round(x-span),Math.round(y+row),span*2,2);}}
const palettes={school:{grass:'#94bd77',light:'#a1c682',dark:'#84ad69',path:'#d9c18d',edge:'#bdab75'},forest:{grass:'#85b373',light:'#95bf7e',dark:'#76a367',path:'#d0b987',edge:'#b5a474'},tokyo:{grass:'#a6b58a',light:'#b1c197',dark:'#8d9e75',path:'#c4bb9f',edge:'#a6a48c'},shibuya:{grass:'#657a77',light:'#718985',dark:'#536c66',path:'#8b9190',edge:'#737b7c'},domain:{grass:'#6a587a',light:'#79688b',dark:'#5b496d',path:'#9684a3',edge:'#7d6b8b'}};
function treeSprite(pink=false,variant=0){const c=canvas(84,100),x=c.getContext('2d');pixelOval(x,42,88,25,8,'#4e734b33');x.fillStyle='#665340';x.fillRect(36,53,12,36);x.fillStyle='#93724c';x.fillRect(39,57,7,30);x.fillStyle='#ac895b';x.fillRect(40,62,2,20);x.fillStyle='#71583e';x.fillRect(29,57,12,6);x.fillRect(46,49,12,7);const p=pink?['#ae7f91','#c88ba1','#e5aabd','#f0c6cc','#f8dad6']:['#487a4b','#5b9255','#76a865','#92bd75','#afd08b'];pixelOval(x,42,43,36,29,p[0]);pixelOval(x,26,48,22,21,p[1]);pixelOval(x,57,45,24,24,p[1]);pixelOval(x,41,29,27,24,p[2]);pixelOval(x,22,36,19,19,p[2]);pixelOval(x,55,30,22,18,p[3]);pixelOval(x,36,21,18,15,p[3]);pixelOval(x,49,17,13,9,p[4]);for(let i=0;i<35;i++){const X=13+(i*17+variant*5)%59,Y=16+(i*11)%49;x.fillStyle=p[(i%3)+1];x.fillRect(X,Y,3+i%3,2);}if(pink){x.fillStyle='#ffe5dc';for(let i=0;i<12;i++)x.fillRect(18+i*13%48,23+i*17%34,2,2);}return c;}
function crystalSprite(){const c=canvas(40,48),x=c.getContext('2d');pixelOval(x,20,42,17,5,'#53765b55');for(const [X,Y,h,w]of [[8,27,19,9],[19,10,32,12],[29,24,18,9]]){x.fillStyle='#407c9b';x.beginPath();x.moveTo(X-w/2,Y+7);x.lineTo(X,Y);x.lineTo(X+w/2,Y+7);x.lineTo(X+w/2,Y+h);x.lineTo(X,Y+h+3);x.lineTo(X-w/2,Y+h);x.fill();x.fillStyle='#77c5d6';x.fillRect(X-w/2+2,Y+8,w/2-1,h-9);x.fillStyle='#b6ebea';x.fillRect(X,Y+5,2,h-4);}return c;}
function lanternSprite(upgrade=0){const c=canvas(36,58),x=c.getContext('2d');pixelOval(x,18,52,16,4,'#3c62483a');x.fillStyle='#6e8477';x.fillRect(10,45,16,8);x.fillRect(14,27,8,20);x.fillStyle='#a9b4a1';x.fillRect(16,29,5,17);x.fillStyle='#59746b';x.fillRect(7,19,22,13);x.fillStyle=upgrade?'#bdf4bf':'#e8d9a6';x.fillRect(11,20,14,9);x.fillStyle='#faf3c8';x.fillRect(15,22,5,5);x.fillStyle='#51766a';x.fillRect(3,15,30,5);x.fillRect(7,11,22,4);x.fillRect(12,7,12,4);x.fillRect(16,3,4,4);x.fillStyle='#8ca593';x.fillRect(5,15,25,2);return c;}
function checkpointSprite(){const c=canvas(48,70),x=c.getContext('2d');pixelOval(x,24,62,22,6,'#58725c55');x.fillStyle='#788c7b';x.fillRect(8,56,32,9);x.fillRect(13,49,22,7);x.fillStyle='#a5b29a';x.fillRect(15,18,18,34);x.fillStyle='#d4dbc1';x.fillRect(18,20,11,29);x.fillStyle='#9a6e56';x.fillRect(5,13,38,5);x.fillRect(10,8,28,5);x.fillStyle='#61776b';x.fillRect(3,10,42,4);x.fillRect(9,5,30,5);x.fillRect(17,1,14,4);x.fillStyle='#aadfd1';x.fillRect(21,23,6,17);x.fillStyle='#f6f6d4';x.fillRect(23,25,2,11);return c;}
function buildingSprite(w=180,h=130,city=false,color='#d6c2a0'){const c=canvas(w+28,h+25),x=c.getContext('2d');x.fillStyle='#4f674b33';x.fillRect(22,h-10,w,25);x.fillStyle='#7c7966';x.fillRect(12,h-22,w,20);x.fillStyle=color;x.fillRect(14,h*.43,w-2,h*.43);x.fillStyle='#b49b76';x.fillRect(14,h*.75,w-2,7);x.fillStyle='#867359';for(let i=0;i<5;i++)x.fillRect(20+i*(w-25)/4,h*.43,5,h*.43);for(let i=0;i<4;i++){let X=30+i*(w-30)/4;x.fillStyle=city?'#739b9e':'#e8d5ad';x.fillRect(X,h*.5,(w-45)/5,h*.25);x.fillStyle='#8f8265';x.fillRect(X+(w-45)/10,h*.5,2,h*.25);x.fillRect(X,h*.62,(w-45)/5,2);}const roof=city?['#647c76','#78938a','#8da296']:['#426a61','#577f70','#729380'];x.fillStyle=roof[0];x.beginPath();x.moveTo(0,h*.47);x.lineTo(21,9);x.lineTo(w-6,9);x.lineTo(w+24,h*.47);x.closePath();x.fill();for(let r=0;r<6;r++){const Y=12+r*(h*.45-12)/6,margin=20-r*3;for(let col=0;col<w/13;col++){let X=margin+col*13+(r%2?6:0);if(X<w+10-margin){x.fillStyle=roof[(r+col)%3===0?2:1];x.fillRect(X,Y,10,3);x.fillStyle=roof[0];x.fillRect(X+9,Y+2,2,6);}}}x.fillStyle=roof[2];x.fillRect(17,7,w-20,4);x.fillStyle=roof[0];x.fillRect(0,h*.47-3,w+25,6);x.fillStyle='#b9b59b';x.fillRect(w*.3,h-8,w*.46,5);x.fillStyle='#d1c7a5';x.fillRect(w*.27,h-3,w*.52,5);x.fillStyle='#e6d9b7';x.fillRect(w*.24,h+2,w*.58,5);if(city){x.fillStyle='#e3cf9e';x.fillRect(w*.36,h*.55,w*.28,16);x.fillStyle='#52766b';x.font='7px monospace';x.fillText('JUJUTSU',w*.39,h*.55+11);}return c;}
function benchSprite(){const c=canvas(60,39),x=c.getContext('2d');pixelOval(x,30,32,27,5,'#496b4733');x.fillStyle='#6c6853';x.fillRect(10,19,4,15);x.fillRect(46,19,4,15);x.fillStyle='#9f7953';x.fillRect(5,8,50,16);x.fillStyle='#d0a978';x.fillRect(5,7,50,4);x.fillRect(5,14,50,4);x.fillRect(5,23,50,5);x.fillStyle='#e0bb88';x.fillRect(7,24,46,2);return c;}
function toriiSprite(){const c=canvas(112,116),x=c.getContext('2d');x.fillStyle='#3a594533';x.fillRect(5,104,104,8);x.fillStyle='#8b5549';x.fillRect(20,19,9,87);x.fillRect(83,19,9,87);x.fillStyle='#c27e64';x.fillRect(22,23,5,79);x.fillRect(85,23,5,79);x.fillRect(13,39,86,8);x.fillRect(5,18,102,8);x.fillStyle='#526b5c';x.fillRect(1,10,110,8);x.fillRect(8,15,96,5);x.fillStyle='#7d8b70';x.fillRect(4,10,103,2);x.fillStyle='#6f796b';x.fillRect(16,99,17,12);x.fillRect(79,99,17,12);x.fillStyle='#c6a66e';x.fillRect(52,24,9,19);return c;}
export class World{
 constructor(container){this.container=container;this.canvas=canvas(1,1);container.appendChild(this.canvas);this.ctx=this.canvas.getContext('2d',{alpha:false});this.renderer={domElement:this.canvas};this.actors=new T.Group();this.fx=new T.Group();this.effects=[];this.heroes=[];this.enemyVisuals=[];this.props=[];this.colliders=[];this.low=matchMedia('(pointer:coarse)').matches;this.mode='paper';this.center={x:0,z:0};this.trees=[treeSprite(false),treeSprite(true),treeSprite(false,2)];this.crystal=crystalSprite();this.checkpoint=checkpointSprite();this.lantern=lanternSprite();this.bench=benchSprite();this.torii=toriiSprite();this.nightFade=0;this.unit=this.low?18:22;this.resize();window.addEventListener('resize',()=>this.resize());}
 resize(){this.width=this.container.clientWidth;this.height=this.container.clientHeight;this.canvas.width=Math.ceil(this.width/2);this.canvas.height=Math.ceil(this.height/2);this.canvas.style.width=this.width+'px';this.canvas.style.height=this.height+'px';this.ctx.imageSmoothingEnabled=false;this.needsRender=true;}
 toScreen(x,z){return {x:Math.round(this.canvas.width/2+(x-this.center.x)*this.unit),y:Math.round(this.canvas.height*(this.low?.51:.57)+(z-this.center.z)*this.unit)};}
 screenToWorld(x,y){return {x:(x/2-this.canvas.width/2)/this.unit+this.center.x,z:(y/2-this.canvas.height*(this.low?.51:.57))/this.unit+this.center.z};}
 prop(x,z,img,w=img.width,h=img.height,kind='prop'){const p={x,z,img,w,h,kind};this.props.push(p);return p;}
 build(id,state){this.effects=[];this.fx.clear();this.region=REGIONS.find(r=>r.id===id);this.state=state;this.props=[];this.colliders=regionColliders(id);this.water=[];const p=palettes[id],u=this.unit;let seed=73+REGIONS.indexOf(this.region)*113;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};this.ground=canvas(36*u,30*u);const c=this.ground.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle=p.grass;c.fillRect(0,0,this.ground.width,this.ground.height);for(let i=0;i<4600;i++){let x=Math.floor(rand()*this.ground.width),y=Math.floor(rand()*this.ground.height);c.fillStyle=i%3?p.light:p.dark;c.fillRect(x,y,2,1);if(i%7===0){c.fillRect(x+1,y-2,1,2);c.fillRect(x-1,y-1,1,1);}}
 const path=(x,z,w,d)=>{const X=(x+18)*u,Y=(z+15)*u;c.fillStyle=p.edge;c.fillRect(Math.floor(X-w*u/2)-1,Math.floor(Y-d*u/2)-1,w*u+2,d*u+2);c.fillStyle=p.path;c.fillRect(Math.floor(X-w*u/2),Math.floor(Y-d*u/2),w*u,d*u);for(let i=0;i<w*d*4;i++){c.fillStyle=i%3?'#f1ddad44':'#a18d642b';c.fillRect(Math.floor(X+(rand()-.5)*w*u),Math.floor(Y+(rand()-.5)*d*u),2,1);}};
 path(0,0,3,28);path(0,3,34,2.5);path(-6,-3,12,2);path(-9,7,3,8);path(9,-6,3,12);if(id==='tokyo'||id==='shibuya'){c.fillStyle=id==='shibuya'?'#65727a':'#8e9690';c.fillRect(14*u,1*u,8*u,28*u);c.fillRect(1*u,15*u,34*u,6*u);c.fillStyle='#d9d9ba';for(let i=0;i<7;i++)c.fillRect((14.5+i)*u,15.5*u,.5*u,5*u);c.fillStyle='#b7bda0';c.fillRect(13.8*u,u,2,28*u);c.fillRect(22*u,u,2,28*u);}
 if(id==='domain'){pixelOval(c,18*u,15*u,11*u,10*u,'#897595');pixelOval(c,18*u,15*u,10.5*u,9.5*u,'#7b658a');for(let i=0;i<12;i++){const a=i/12*Math.PI*2;c.fillStyle='#ad95b4';c.fillRect(18*u+Math.sin(a)*8.5*u,15*u+Math.cos(a)*8*u,3,3);}}
 const addBuilding=(x,z,w,d,city=false)=>{const img=buildingSprite(w*u,(city?5:4.8)*u,city);this.prop(x,z+d/2,img,img.width,img.height,'building');};
 if(id==='school'){for(const b of regionBuildings(id))addBuilding(b.x,b.z,b.w,b.d);this.prop(-11,8,this.torii,4*u,4.2*u);for(const p of regionPonds(id))this.pond(p.x,p.z,p.rx,p.rz);this.prop(-5,5,this.bench,2.5*u,1.6*u);this.prop(4,9,this.bench,2.5*u,1.6*u);for(const [x,z]of [[-3,-4],[3,-4],[-11,6],[6,5]])this.prop(x,z,this.lantern,1.5*u,2.4*u);}
 else if(id==='forest'){for(const p of regionPonds(id))this.pond(p.x,p.z,p.rx,p.rz);this.prop(9,-9,this.torii,4*u,4.2*u);for(const b of regionBuildings(id))addBuilding(b.x,b.z,b.w,b.d);this.prop(-5,8,this.bench,2.5*u,1.6*u);for(const [x,z]of [[-8,6],[9,-7],[-2,-5],[8,5]])this.prop(x,z,this.lantern,1.5*u,2.4*u);}
 else if(id==='tokyo'||id==='shibuya'){for(const b of regionBuildings(id))addBuilding(b.x,b.z,b.w,b.d,true);const vending=canvas(30,45),v=vending.getContext('2d');v.fillStyle='#487b79';v.fillRect(2,2,26,41);v.fillStyle='#8cc8c3';v.fillRect(5,6,20,23);v.fillStyle='#e9dbb2';for(let j=0;j<6;j++)v.fillRect(7+j%3*6,9+Math.floor(j/3)*10,3,7);v.fillStyle='#284f55';v.fillRect(6,33,14,5);this.prop(-7,8,vending,1.4*u,2*u);}
 else{this.prop(0,10,this.torii,4*u,4.2*u);for(let i=0;i<10;i++){const a=i/10*Math.PI*2;this.prop(Math.sin(a)*12,Math.cos(a)*10,this.crystal,2*u,3*u);}}
 for(let i=0;i<48;i++){const x=(rand()-.5)*33,z=(rand()-.5)*26;if(Math.abs(x)<3||Math.abs(z-3)<2||id==='domain'||id==='tokyo'||id==='shibuya')continue;if(this.colliders.some(c=>Math.abs(x-c.x)<c.w/2+1.5&&Math.abs(z-c.z)<c.d/2+1.5))continue;if(this.water.some(w=>Math.hypot((x-w.x)/w.rx,(z-w.z)/w.rz)<1.3))continue;this.prop(x,z,this.trees[i%3===0?1:0],3.5*u,4.2*u,'tree');}
 // Dense forest edges frame the map without a diorama border.
 if(id==='school'||id==='forest')for(let i=0;i<23;i++){for(const z of [-14,14])this.prop(-17+i*1.5,z,this.trees[(i+1)%3],3.5*u,4.2*u,'tree');}
 for(const o of state.objects){if(o.region!==id)continue;o.visual={visible:!o.depleted};}
 this.colliders=regionColliders(id);this.center={x:state.heroes[state.controlled].x,z:state.heroes[state.controlled].z};this.nightFade=Number(state.clock>=18||state.clock<6||id==='domain'||id==='shibuya');this.needsRender=true;}
 pond(x,z,rx,rz){const u=this.unit,c=this.ground.getContext('2d'),X=(x+18)*u,Y=(z+15)*u;pixelOval(c,X,Y,rx*u+5,rz*u+5,'#a99c72');pixelOval(c,X,Y,rx*u+2,rz*u+2,'#c5bd88');pixelOval(c,X,Y,rx*u,rz*u,'#579ea8');pixelOval(c,X,Y-3,rx*u-5,rz*u-5,'#73bdc3');this.water.push({x,z,rx,rz});c.fillStyle='#577e60';for(let i=0;i<8;i++){const a=i/8*7;let xx=X+Math.sin(a)*(rx*u+3),yy=Y+Math.cos(a)*(rz*u+3);c.fillRect(xx,yy-5,1,7);c.fillRect(xx+3,yy-3,1,5);}const dock=canvas(50,70),d=dock.getContext('2d');d.fillStyle='#8e714f';d.fillRect(3,0,44,68);for(let j=0;j<9;j++){d.fillStyle=j%2?'#c19d6c':'#cfac7a';d.fillRect(4,2+j*7,42,5);}d.fillStyle='#e0bf8d';d.fillRect(6,0,2,68);d.fillRect(41,0,2,68);this.prop(x,z+rz+1,dock,2*u,2.8*u,'dock');}
 createHero(id){const group=new T.Group();this.actors.add(group);const v={id,group,canvas:canvas(128,128),lastKey:'',gear:'blindfold',clip:0,frame:0,direction:'south',selected:false};this.heroes.push(v);return v;}
 updateHero(v,a,t,selected=false){v.group.position.set(a.x,0,a.z);v.selected=selected;v.actor=a;let clip=a.hp<=0?19:a.animTime>0?a.clip:a.sitting?7:a.moving?3:0;let dir=a.moving||a.animTime>0?(Math.abs(a.facing.x)>.75?'side':a.facing.z<0?'north':'south'):'south';if(dir==='side'&&a.facing.x<0)dir='west';if(clip===0)clip=dir==='north'?1:['side','west'].includes(dir)?2:0;if(clip===3)clip=dir==='north'?4:['side','west'].includes(dir)?5:3;const c=CLIPS[clip],frame=Math.floor((a.animTime>0?a.animElapsed:t)*c.fps)%c.frames,gear=a.awake>0?'eyes':a.gear,key=`${clip}-${frame}-${dir}-${gear}`;Object.assign(v,{clip,frame,direction:dir,gear});if(key!==v.lastKey){const ctx=v.canvas.getContext('2d');ctx.clearRect(0,0,128,128);drawHero(ctx,v.id,clip,frame,dir,gear);v.lastKey=key;}}
 createEnemy(e){const sprite=new T.Sprite(new T.SpriteMaterial({transparent:true}));this.actors.add(sprite);const v={sprite,canvas:canvas(128,128),last:-1,enemy:e};this.enemyVisuals.push(v);return v;}
 updateEnemy(e,t){const v=e.visual;v.sprite.position.set(e.x,0,e.z);const frame=Math.floor(t*12);if(frame!==v.last){const c=v.canvas.getContext('2d');c.clearRect(0,0,128,128);drawEnemyAnimation(c,e,e.stun>0?'hurt':e.telegraph>0?'telegraph':e.attackTime>0?'attack':'walk',frame%8);v.last=frame;}}
 removeEnemy(e){if(!e.visual)return;const v=e.visual;this.enemyVisuals=this.enemyVisuals.filter(x=>x!==v);this.actors.remove(v.sprite);const img=canvas(128,128);img.getContext('2d').drawImage(v.canvas,0,0);const m=new T.Object3D();m.position.set(e.x,0,e.z);m.material={opacity:1,transparent:true,dispose(){}};this.effects.push({type:'defeat',m,img,life:.5,total:.5,size:e.maxHp>500?2.4:1.6});}
 effect(type,x,z,color='#b9eed6',size=1,duration=.6,dx=0,dz=0){const m=new T.Object3D();m.position.set(x,.25,z);m.material={opacity:1,transparent:true,dispose(){}};this.fx.add(m);const e={m,type,color,size,life:duration,total:duration,dx,dz};this.effects.push(e);return e;}
 floating(text,x,z,color='#fff1cb'){const e=this.effect('text',x,z,color,1,1.3);e.text=text;return e;}
 drawImage(img,x,z,w,h,alpha=1){const p=this.toScreen(x,z);this.ctx.globalAlpha=alpha;this.ctx.drawImage(img,Math.round(p.x-w/2),Math.round(p.y-h*.9),Math.round(w),Math.round(h));this.ctx.globalAlpha=1;}
 drawResource(o){const u=this.unit,c=this.ctx,p=this.toScreen(o.x,o.z);if(o.depleted)return;if(o.type==='tree'){const sway=Math.sin((o.shake||0)*22)*Math.exp(-(o.shake||0)*3);this.drawImage(this.trees[1],o.x+sway*.05,o.z,3.3*u,4*u);}else if(o.type==='crystal')this.drawImage(this.crystal,o.x,o.z,1.7*u,2*u);else if(o.type==='lantern')this.drawImage(lanternSprite(o.upgrade),o.x,o.z,1.5*u,2.4*u);else{c.fillStyle=o.growth>0?'#8a674b':'#a5815a';c.fillRect(p.x-u*.65,p.y-u*.6,u*1.3,u*1.1);for(let i=0;i<4;i++){let x=p.x+(i%2-.5)*u*.6,y=p.y+(Math.floor(i/2)-.5)*u*.5;c.fillStyle='#684e3e';c.fillRect(x-4,y+2,9,2);c.fillStyle='#4e854c';c.fillRect(x,y-5-o.growth*5,2,9+o.growth*5);c.fillStyle='#8bbe66';c.fillRect(x-4,y-4-o.growth*4,5,3);c.fillRect(x+2,y-6-o.growth*4,4,3);if(o.growth>=1){c.fillStyle='#e8c59b';c.fillRect(x-2,y-10,6,5);c.fillStyle='#f4dcc0';c.fillRect(x-1,y-10,3,2);}}}}
 drawHeroVisual(v){const p=v.group.position,u=this.unit,c=this.ctx,screen=this.toScreen(p.x,p.z);pixelOval(c,screen.x,screen.y+1,u*.4,u*.14,'#35533940');if(v.selected){c.strokeStyle='#f6e4ac';c.lineWidth=1;c.strokeRect(screen.x-u*.49,screen.y-u*.2,u*.98,u*.32);}this.drawImage(v.canvas,p.x,p.z,u*1.8,u*1.8,v.actor.hp<=0?.5:1);}

 drawEffect(e){const c=this.ctx,u=this.unit,p=this.toScreen(e.m.position.x,e.m.position.z),q=1-e.life/e.total;c.save();c.globalAlpha=Math.max(0,e.life/e.total);if(['ring','zone','warning'].includes(e.type)){c.strokeStyle=e.color;c.lineWidth=e.type==='warning'?2:1;c.setLineDash(e.type==='warning'?[4,3]:[]);c.beginPath();c.ellipse(p.x,p.y,e.size*u*(1+q*.3),e.size*u*(1+q*.3)*.5,0,0,7);c.stroke();if(e.type==='zone'){c.globalAlpha*=.13;c.fillStyle=e.color;c.fill();}}else if(e.type==='beam'){c.strokeStyle=e.color;c.lineWidth=e.size*u*1.5;c.globalAlpha*=.6;c.beginPath();c.moveTo(p.x,p.y-u*.6);c.lineTo(p.x+e.dx*16*u,p.y+e.dz*16*u-u*.6);c.stroke();c.strokeStyle='#fff2ff';c.lineWidth=2;c.stroke();}else if(e.type==='orb'){pixelOval(c,p.x,p.y-u*.5,e.size*u*1.4,e.size*u*1.4,e.color+'55');pixelOval(c,p.x,p.y-u*.5,e.size*u,e.size*u,e.color);pixelOval(c,p.x-2,p.y-u*.5-2,e.size*u*.4,e.size*u*.4,'#fff4ef');}else if(e.type==='text'){c.font='bold 7px monospace';c.textAlign='center';c.strokeStyle='#314c3c';c.lineWidth=2;c.strokeText(e.text,p.x,p.y-u*(1.5+q));c.fillStyle=e.color;c.fillText(e.text,p.x,p.y-u*(1.5+q));}else if(e.type==='defeat'){c.translate(p.x,p.y);c.rotate(q*.7);c.drawImage(e.img,-e.size*u/2,-e.size*u,e.size*u,e.size*u);}c.restore();}
 tick(dt,t,player,night){this.center.x+=(player.x-this.center.x)*Math.min(1,dt*7);this.center.z+=(player.z-this.center.z)*Math.min(1,dt*7);const c=this.ctx,u=this.unit;c.imageSmoothingEnabled=false;c.fillStyle=palettes[this.region.id].dark;c.fillRect(0,0,this.canvas.width,this.canvas.height);const origin=this.toScreen(-18,-15);c.drawImage(this.ground,origin.x,origin.y);for(const w of this.water){const p=this.toScreen(w.x,w.z);c.fillStyle='#b8e4d0';for(let i=0;i<7;i++){const x=p.x+Math.sin(i*2.8+t*.25)*w.rx*u*.7,y=p.y+Math.cos(i*1.7)*w.rz*u*.75;c.fillRect(Math.round(x),Math.round(y+Math.sin(t*2+i)*2),4+i%4,1);}c.fillStyle='#699e75';c.fillRect(p.x-8,p.y+5,8,3);c.fillStyle='#d6b6bc';c.fillRect(p.x-6,p.y+3,3,3);}
 const list=this.props.map(p=>({z:p.z,draw:()=>this.drawImage(p.img,p.x,p.z,p.w,p.h)}));for(const o of this.state.objects.filter(o=>o.region===this.region.id&&!o.depleted))list.push({z:o.z,draw:()=>this.drawResource(o)});
 for(const cp of this.region.checkpoints){const [name,x,z]=cp;list.push({z,draw:()=>{this.drawImage(this.checkpoint,x,z,2*u,2.9*u);const p=this.toScreen(x,z);c.fillStyle='#c4f0d955';pixelOval(c,p.x,p.y,u*.8,u*.25,'#b2e5d547');}});}
 for(const v of this.heroes)if(v.group.visible)list.push({z:v.group.position.z,draw:()=>this.drawHeroVisual(v)});for(const v of this.enemyVisuals)list.push({z:v.sprite.position.z,draw:()=>this.drawImage(v.canvas,v.sprite.position.x,v.sprite.position.z,u*(v.enemy.maxHp>500?2.6:1.8),u*(v.enemy.maxHp>500?2.6:1.8))});
 for(const m of this.actors.children){if(m.isSprite&&m.material.map?.image)list.push({z:m.position.z,draw:()=>this.drawImage(m.material.map.image,m.position.x,m.position.z-(m.position.y-.25),m.scale.x*u,m.scale.y*u)});}
 for(const m of this.fx.children){if(m.isMesh)list.push({z:m.position.z,draw:()=>{const p=this.toScreen(m.position.x,m.position.z);c.fillStyle='#e6c58b';c.fillRect(p.x-2,p.y-m.position.y*u,5,4);}});}
 list.sort((a,b)=>a.z-b.z);for(const o of list)o.draw();
 this.nightFade+=(Number(night)-this.nightFade)*Math.min(1,dt*2);if(this.nightFade>.01){c.fillStyle=`rgba(32,28,69,${this.nightFade*.43})`;c.fillRect(0,0,this.canvas.width,this.canvas.height);for(const [name,x,z]of this.region.checkpoints){const p=this.toScreen(x,z);pixelOval(c,p.x,p.y-u,12,17,'#b5f1d822');pixelOval(c,p.x,p.y-u,6,10,'#d8f4ce33');}}
 for(const [to,x,z]of this.region.exits){const p=this.toScreen(x,z),name=REGIONS.find(r=>r.id===to).name.replace('Tokyo ','').replace(' · The Curtain','');c.font='6px monospace';const w=c.measureText(name).width+12;c.fillStyle='#67573d';c.fillRect(p.x-w/2,p.y-u*1.7,w,14);c.fillStyle='#ead8ad';c.fillRect(p.x-w/2+1,p.y-u*1.7+1,w-2,12);c.fillStyle='#58684b';c.textAlign='center';c.fillText('→ '+name,p.x,p.y-u*1.7+9);}
 for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.life-=dt;if(e.type==='orb'){e.m.position.x+=(e.dx||0)*dt;e.m.position.z+=(e.dz||0)*dt;}this.drawEffect(e);if(e.life<=0){this.fx.remove(e.m);this.effects.splice(i,1);}}
 // Floating blossom petals and fireflies stay in the 2D scene.
 c.fillStyle=night?'#e5e8a6aa':'#f2c6cfaa';for(let i=0;i<(this.low?9:23);i++){const x=(i*73+t*3)%this.canvas.width,y=(i*47+t*5)%this.canvas.height;c.fillRect(Math.floor(x),Math.floor(y),2,1);} }
 canMove(x,z){return Math.abs(x)<16.3&&Math.abs(z)<13.2&&!this.colliders.some(c=>Math.abs(x-c.x)<c.w/2+.2&&Math.abs(z-c.z)<c.d/2+.2);}
}
